using MediatR; using Microsoft.AspNetCore.Http; using Rentify.Backend.Core.Application.Modules.Reservations.Contracts.Repositories; using Rentify.Backend.Core.Application.Modules.Reservations.Dtos; using Rentify.Backend.Core.Application.Modules.Reservations.Mappers; using Rentify.Backend.Core.Application.Modules.Reservations.Services; using Rentify.Backend.Core.Application.Modules.Shared.Exceptions; using Rentify.Backend.Core.Application.Modules.Shared.Response; using Rentify.Backend.Core.Application.Modules.Shared.UnitOfWork; using Rentify.Backend.Core.Domain.Entities.Reservations;
namespace Rentify.Backend.Core.Application.Modules.Reservations.Commands;
public sealed class UpdateReservationCommandHandler : IRequestHandler<UpdateReservationCommand, ResultReponse<ReservationResponse>> { private readonly IReservationRepository _reservationRepository; private readonly IReservationVehicleResolver _vehicleResolver; private readonly IReservationLocationResolver _locationResolver; private readonly IUnitOfWork _unitOfWork; public UpdateReservationCommandHandler(IReservationRepository reservationRepository, IReservationVehicleResolver vehicleResolver, IReservationLocationResolver locationResolver, IUnitOfWork unitOfWork) { _reservationRepository = reservationRepository; _vehicleResolver = vehicleResolver; _locationResolver = locationResolver; _unitOfWork = unitOfWork; } public async Task<ResultReponse<ReservationResponse>> Handle(UpdateReservationCommand request, CancellationToken cancellationToken) { Reservation reservation = await _reservationRepository.GetByIdAsync(request.TenantId, request.ReservationId, cancellationToken) ?? throw new ApiException("Reserva no encontrada.", StatusCodes.Status404NotFound); var vehicle = await _vehicleResolver.GetReservableVehicleAsync(request.TenantId, reservation.VehicleId, cancellationToken); var delivery = await _locationResolver.ResolveDeliveryAsync(request.TenantId, request.DeliveryTenantLocationId, request.DeliveryLocationName, request.DeliveryFee, cancellationToken); var returns = await _locationResolver.ResolveReturnAsync(request.TenantId, request.ReturnTenantLocationId, request.ReturnLocationName, request.ReturnFee, cancellationToken); var rate = _vehicleResolver.GetRateOrThrow(vehicle, request.RentalType); int quantity = Reservation.CalculateQuantity(request.DeliveryDateTime, request.ExpectedReturnDateTime, request.RentalType); reservation.UpdatePendingReservation(request.DeliveryDateTime, request.ExpectedReturnDateTime, request.RentalType, quantity, rate.Price, vehicle.SecurityDepositRequired, vehicle.SecurityDepositAmount, delivery.TenantLocationId, delivery.Name, request.DeliveryAddressDetails, delivery.Fee, returns.TenantLocationId, returns.Name, request.ReturnAddressDetails, returns.Fee, request.DiscountAmount, reservation.Channel, request.Notes, request.ModifiedBy); await _unitOfWork.SaveChangesAsync(cancellationToken); return ResultReponse<ReservationResponse>.Success(reservation.ToResponse()); } }
